'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const shores=[{size:8,title:['The lantern inlet','燈籠灣']},{size:16,title:['The moon arch','月亮拱門']},{size:32,title:['The hidden harbor','隱藏港口']}];
let variant=OrionProgress.variant('mist'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,low=1,high=8,solved=false,history=[],hintDepth=0,state='ready',last=null,removed=0,saveFailed=false,records=[];
function targetFor(v,s){return ([2,10,20][s]+v*3)%shores[s].size+1;}
function clue(n,target){return n===target?'found':n<target?'higher':'lower';}
function middle(){return Math.floor((low+high)/2);}
function resetShore(){low=1;high=shores[stage].size;solved=false;history=[];hintDepth=0;state='ready';last=null;removed=0;saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('mist')){variant=v;stage=0;records=[];resetShore();}
function probe(n){if(solved)return;if(!Number.isInteger(n)||n<low||n>high){state='invalid';render();return;}const old=high-low+1,result=clue(n,targetFor(variant,stage));last=n;
 if(result==='higher')low=n+1;else if(result==='lower')high=n-1;else{low=high=n;solved=true;records[stage]=history.length+1;if(stage===2)saveFailed=!OrionProgress.earn('mist');}
 removed=old-(high-low+1);history.unshift({n,result,low,high,removed});state=result;render();if(solved&&stage<2)$('next').focus();}
function hints(){const mid=middle();return [t('A clue applies to a whole group of cave numbers, not just the cave you tried.','一個線索適用於整組洞穴號碼，不只適用於你試過的洞穴。'),t('A cave near the middle splits the remaining possibilities into two similar groups. Which middle would you try?','靠近中間的洞穴，把剩餘可能分成大小相近的兩組。你會試哪個中間號碼？'),t(`The remaining range is ${low}–${high}. Try cave ${mid}, then use the new clue.`,`剩餘範圍是 ${low}–${high}。試洞穴 ${mid}，再利用新的線索。`)];}
function render(){const c=shores[stage],complete=solved&&stage===2,count=stage+(solved?1:0);document.title=t('The Mist Keeper · Orion','霧海守望者 · Orion');$('progressCount').textContent=t(`Boats found · ${count} / 3`,`已找到 ${count} / 3 艘船`);$('progressBar').value=count;$('stageLabel').textContent=t(`SHORE ${stage+1} · ${c.size} CAVES`,`海岸 ${stage+1} · ${c.size} 個洞穴`);$('stageTitle').textContent=t(...c.title);$('mission').textContent=t(`One boat is hidden among caves 1–${c.size}. Choose a cave. The keeper will tell you whether its number is higher or lower.`,`一艘船藏在洞穴 1–${c.size}。選一個洞穴，守望者會告訴你目標號碼更大還是更小。`);
 $('caves').innerHTML=Array.from({length:c.size},(_,i)=>{const n=i+1,excluded=n<low||n>high,found=solved&&n===last;return `<button type="button" class="cave ${found?'found':''}" data-cave="${n}" ${solved||excluded?'disabled':''} aria-label="${t(`Cave ${n}${found?', boat found':excluded?', ruled out':''}`,`洞穴 ${n}${found?'，找到船了':excluded?'，已排除':''}`)}">${found?'⚓ ':''}${n}</button>`;}).join('');
 const messages={ready:t('Choose a cave to begin. Every answer is evidence.','選一個洞穴開始。每個回答都是證據。'),invalid:t('That cave is outside the remaining range. Try a lit cave.','那個洞穴已不在剩餘範圍內。試試亮著的洞穴。'),higher:t(`↑ Higher than ${last}. Rule out caves up to ${last}.`,`↑ 比 ${last} 大。排除 ${last} 及所有更小的洞穴。`),lower:t(`↓ Lower than ${last}. Rule out cave ${last} and all larger numbers.`,`↓ 比 ${last} 小。排除 ${last} 及所有更大的洞穴。`),found:t(`Boat found in cave ${last}! ${complete?'The Mist Sigil is yours.':'A map fragment is recovered.'}`,`在洞穴 ${last} 找到船了！${complete?'你獲得迷霧符印。':'尋回一片地圖碎片。'}`)};
 $('feedback').textContent=messages[state];$('range').textContent=solved?t(`Cave ${last} · found`,`洞穴 ${last} · 找到了`):`${low} — ${high}`;$('remaining').textContent=t(`${high-low+1} possible cave${high===low?'':'s'}${removed?` · ${removed} ruled out this time`:''}`,`尚有 ${high-low+1} 個可能洞穴${removed?` · 這次排除 ${removed} 個`:''}`);$('attempts').textContent=t(`Questions asked: ${history.length}`,`已詢問 ${history.length} 次`);
 $('next').hidden=!solved||stage===2;$('retry').hidden=solved;$('reward').hidden=!complete;$('notes').hidden=!complete;$('scene').classList.toggle('complete',complete);$('scene').style.setProperty('--cleared',String(count/3));$('seals').textContent=shores.map((_,i)=>i<count?'◆':'◇').join(' ');$('sceneStatus').textContent=complete?t('The harbor passage is open.','港口航道開啟了。'):t('Follow the clues through the mist.','循著線索，穿越迷霧。');
 $('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hint').disabled=hintDepth===3||solved;$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(x=>`<li>${x}</li>`).join('');
 $('log').innerHTML=history.map(h=>`<li>${h.n} → ${t(h.result==='higher'?'higher':h.result==='lower'?'lower':'found',h.result==='higher'?'更大':h.result==='lower'?'更小':'找到了')} · ${h.low}–${h.high}</li>`).join('')||`<li>${t('Your clues will appear here.','你的線索會顯示在這裡。')}</li>`;
 $('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but this browser could not save it. Try saving again.','已獲得符印，但瀏覽器無法儲存。請再次嘗試。'):OrionProgress.has('mist')?t('Mist Sigil saved in your collection.','迷霧符印已存入你的收藏。'):'';
 $('efficiency').textContent=t(`Your three searches used ${records.join(', ')} questions. Choosing a middle cave each time finds any boat in at most 4, 5 and 6 questions on these shores. You can replay to explore this strategy; there is no time limit.`,`你三次搜尋用了 ${records.join('、')} 次詢問。每次選中間洞穴，在這三片海岸分別最多只需 4、5、6 次就能找到任何船。你可以再次探索這個方法，沒有時間限制。`);
}
$('caves').addEventListener('click',e=>{const button=e.target.closest('[data-cave]');if(button&&!button.disabled)probe(Number(button.dataset.cave));});
$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetShore();$('caves').querySelector('button:not(:disabled)')?.focus();};$('retry').onclick=()=>{if(!solved)resetShore();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const next=OrionProgress.nextVariant('mist',variant);observedVariant=OrionProgress.variant('mist');resetMission(next);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('mist');render();};
function syncProgress(){const v=OrionProgress.variant('mist'),target=OrionProgress.read().hashTarget;const changed=v!==observedVariant||target!==observedTarget;observedVariant=v;observedTarget=target;if(changed||solved&&stage===2&&!OrionProgress.has('mist')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
